    public String getList(String fqdnList) {

        String url = baseUrl + "/lists/" + fqdnList;

        HttpEntity entity =
                new HttpEntity<>(headers());

        ResponseEntity response =
                restTemplate.exchange(
                        url,
                        HttpMethod.GET,
                        entity,
                        String.class
                );

        return response.getBody();
    }

    public String createList(String fqdnList,
                             String displayName,
                             String adminEmail) {

        String url = baseUrl + "/lists";

        Map body = Map.of(
                "fqdn_listname", fqdnList,
                "display_name", displayName,
                "admin_email", adminEmail
        );

        HttpEntity<Map> entity =
                new HttpEntity<>(body, headers());

        ResponseEntity response =
                restTemplate.exchange(
                        url,
                        HttpMethod.POST,
                        entity,
                        String.class
                );

        return response.getBody();
    }
