package com.example.mailman;

import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/mailman")
public class MailmanController {

    private final MailmanClient mailmanClient;

    public MailmanController(MailmanClient mailmanClient) {
        this.mailmanClient = mailmanClient;
    }

    @GetMapping("/lists")
    public String lists() {
        return mailmanClient.getLists();
    }

    @GetMapping("/lists/{list}")
    public String list(@PathVariable String list) {
        return mailmanClient.getList(list);
    }

    @PostMapping("/lists")
    public String createList(
            @RequestParam String list,
            @RequestParam String displayName,
            @RequestParam String adminEmail) {

        return mailmanClient.createList(
                list,
                displayName,
                adminEmail
        );
    }
}

